INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('inside_prayer', 'event', '«اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْنِي مِنْ خَطَايَايَ بِالثَّلْجِ وَالْمَاءِ وَالْبَرَدِ»', 'O Allaah, plaats tussen mij en mijn zonden dezelfde afstand als tussen het oosten en het westen. O Allaah, reinig mij van mijn zonden zoals het witte kleed van vuil wordt gereinigd. O Allaah, was mij van mijn zonden met sneeuw, water en hagel.', 'O Allaah, distance me from my sins as You have distanced the east from the west. O Allaah, cleanse me of my sins as a white garment is cleansed of filth. O Allaah, wash me of my sins with snow, water and hail.', '', '', '', 'لم يرد فيه أجر مخصوص، وهو أصح الاستفتاحات في الفريضة.', 'Geen specifieke beloning overgeleverd; het is de meest authentieke opening in het verplichte gebed.', 'No specific reward reported; it is the most authentic opening in the obligatory prayer.', 'دعاء الاستفتاح بالمباعدة عن الخطايا', 'eredienst', 'act of worship', 1, 61),('inside_prayer', 'event', '«سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرُكَ»', 'Verheven bent U, o Allaah, en aan U alle lof; gezegend is Uw Naam, verheven is Uw majesteit, en er is geen god buiten U.', 'Glory be to You, O Allaah, and praise be to You; blessed is Your Name, exalted is Your majesty, and there is no god other than You.', '', '', '', 'لم يرد فيه أجر مخصوص، وهو استفتاح ثناء محض.', 'Geen specifieke beloning overgeleverd; het is een zuivere lof-opening.', 'No specific reward reported; it is a pure opening of praise.', 'دعاء الاستفتاح بالتسبيح', 'eredienst', 'act of worship', 1, 62),('inside_prayer', 'event', '«وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ، وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ. اللَّهُمَّ أَنْتَ الْمَلِكُ لَا إِلَهَ إِلَّا أَنْتَ، أَنْتَ رَبِّي وَأَنَا عَبْدُكَ، ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي، فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، وَاهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ»', 'Ik heb mijn aangezicht gewend tot Degene Die de hemelen en de aarde heeft geschapen, als rechtzinnige, en ik behoor niet tot de veelgodenaanbidders. Waarlijk, mijn gebed, mijn offer, mijn leven en mijn sterven behoren Allaah toe, de Heer der werelden; Hij heeft geen deelgenoot, en dat is mij bevolen, en ik behoor tot de moslims. O Allaah, U bent de Koning, er is geen god behalve U. U bent mijn Heer en ik ben Uw dienaar. Ik heb mijzelf onrecht aangedaan en ik erken mijn zonde; vergeef mij dus al mijn zonden, want niemand vergeeft de zonden behalve U. Leid mij naar het beste gedrag, want niemand leidt naar het beste ervan behalve U, en wend het slechte ervan van mij af, want niemand wendt het slechte ervan van mij af behalve U.', 'I have turned my face to the One who originated the heavens and the earth, inclining to truth, and I am not of the polytheists. Indeed my prayer, my sacrifice, my living and my dying are for Allaah, Lord of the worlds; He has no partner, and thus I have been commanded, and I am of the Muslims. O Allaah, You are the King; none has the right to be worshipped except You. You are my Lord and I am Your slave. I have wronged myself and I confess my sin, so forgive me all my sins, for none forgives sins except You. Guide me to the best of character, for none guides to its best except You, and turn its evil away from me, for none turns its evil away except You.', '', '', '', 'لم يرد فيه أجر مخصوص، وأصله في استفتاح صلاة الليل.', 'Geen specifieke beloning overgeleverd; het heeft zijn oorsprong in de opening van het nachtgebed.', 'No specific reward reported; its origin is in the opening of the night prayer.', 'دعاء الاستفتاح بالتوجيه', 'eredienst', 'act of worship', 1, 63),('inside_prayer', 'event', '«سُبْحَانَ رَبِّيَ الْعَظِيمِ»', 'Verheven is mijn Heer, de Geweldige (in de roekoe3).', 'Glory be to my Lord, the Magnificent (in bowing).', '', '', '', 'لم يرد فيه أجر مخصوص، وأجره عموم فضل الذكر في الصلاة.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'تسبيح الركوع', 'eredienst', 'act of worship', 1, 64),('inside_prayer', 'event', '«سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي»', 'Verheven bent U, o Allaah, onze Heer, en aan U alle lof; o Allaah, vergeef mij (in roekoe3 en soedjoed).', 'Glory be to You, O Allaah, our Lord, and praise be to You; O Allaah, forgive me (in bowing and prostration).', '', '', '', 'فيه امتثاله صلى الله عليه وسلم قوله تعالى: ﴿فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ﴾.', 'Daarin volgt hij (vrede en zegeningen zij met hem) Allaahs woord: ''Verheerlijk de lof van jouw Heer en vraag Hem om vergeving''.', 'Therein he follows (peace and blessings be upon him) Allaah''s saying: ''Glorify the praise of your Lord and seek His forgiveness''.', 'تسبيح الركوع بالمغفرة', 'eredienst', 'act of worship', 1, 65),('inside_prayer', 'event', '«سُبُّوحٌ قُدُّوسٌ، رَبُّ الْمَلَائِكَةِ وَالرُّوحِ»', 'Volmaakt Verheven, Volmaakt Heilig, Heer van de engelen en van de Roeh (in roekoe3 en soedjoed).', 'All-Glorified, All-Holy, Lord of the angels and the Spirit (in bowing and prostration).', '', '', '', 'لم يرد فيه أجر مخصوص، وأجره عموم فضل الذكر في الصلاة.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'تسبيح سبوح قدوس', 'eredienst', 'act of worship', 1, 66),('inside_prayer', 'event', '«سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ»', 'Allaah hoort wie Hem prijst — onze Heer, en aan U alle lof.', 'Allaah hears whoever praises Him — our Lord, and to You is all praise.', '', '', '', 'لم يرد فيه أجر مخصوص، وأجره عموم فضل الذكر في الصلاة.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'ذكر الرفع من الركوع', 'eredienst', 'act of worship', 1, 67),('inside_prayer', 'event', '«اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ، أَهْلَ الثَّنَاءِ وَالْمَجْدِ، أَحَقُّ مَا قَالَ الْعَبْدُ، وَكُلُّنَا لَكَ عَبْدٌ: اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ»', 'O Allaah, onze Heer, aan U alle lof: de vulling van de hemelen, de vulling van de aarde en de vulling van wat U daarnaast wilt. Bezitter van lof en glorie — het meest ware wat de dienaar zegt, en wij allen zijn dienaren van U: o Allaah, niemand kan tegenhouden wat U geeft, niemand kan geven wat U tegenhoudt, en de rijkdom van de rijke baat hem bij U niet.', 'O Allaah, our Lord, to You is all praise: filling the heavens, filling the earth, and filling whatever else You will. Worthy of praise and glory — the truest thing a slave says, and all of us are Your slaves: O Allaah, none can withhold what You give, none can give what You withhold, and the wealth of the wealthy avails him nothing against You.', '', '', '', 'لم يرد فيه أجر مخصوص، وأجره عموم فضل الذكر في الصلاة.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'تحميد الرفع من الركوع', 'eredienst', 'act of worship', 1, 68),('inside_prayer', 'event', '«سُبْحَانَ رَبِّيَ الْأَعْلَى»', 'Verheven is mijn Heer, de Hoogste (in de soedjoed).', 'Glory be to my Lord, the Most High (in prostration).', '', '', '', 'لم يرد فيه أجر مخصوص، وأجره عموم فضل الذكر في الصلاة.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'تسبيح السجود', 'eredienst', 'act of worship', 1, 69),('inside_prayer', 'event', '«اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ: دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَتَهُ وَسِرَّهُ»', 'O Allaah, vergeef mij al mijn zonden: de kleine en de grote, de eerste en de laatste, de openlijke en de verborgene.', 'O Allaah, forgive me all my sins: the small and the great, the first and the last, the open and the secret.', '', '', '', 'لم يرد فيه أجر مخصوص، وأجره عموم فضل الذكر في الصلاة.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستغفار الجامع في السجود', 'eredienst', 'act of worship', 1, 70),('inside_prayer', 'event', '«أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ؛ فَأَكْثِرُوا الدُّعَاءَ»', 'De dienaar is het dichtst bij zijn Heer wanneer hij zich neerknielt; verricht dus veelvuldig smeekbeden in de soedjoed.', 'The slave is nearest to his Lord while prostrating; so supplicate much in prostration.', '', '', '', 'الأجر مبين: السجود أقرب أحوال العبد من ربه فدعاؤه فيه حري بالإجابة.', 'De beloning is toegelicht: de soedjoed is de nauwste staat van de dienaar bij zijn Heer, dus zijn smeekbede daarin verdient verhoring.', 'The reward is explained: prostration is the servant''s nearest state to his Lord, so his supplication in it merits an answer.', 'ويكثر من الدعاء في سجوده؛ لقوله ﷺ', 'eredienst', 'act of worship', 1, 71),('inside_prayer', 'event', '«رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي»', 'Mijn Heer, vergeef mij; mijn Heer, vergeef mij (tussen de twee soedjoeds).', 'My Lord, forgive me; my Lord, forgive me (between the two prostrations).', '', '', '', 'لم يرد فيه أجر مخصوص، وأجره عموم فضل الذكر في الصلاة.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بين السجدتين', 'eredienst', 'act of worship', 1, 72),('inside_prayer', 'event', '«اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَاجْبُرْنِي، وَعَافِنِي، وَارْزُقْنِي، وَارْفَعْنِي»', 'O Allaah, vergeef mij, wees mij genadig, leid mij, herstel mij, schenk mij gezondheid, voorzie mij en verhef mij.', 'O Allaah, forgive me, have mercy on me, guide me, mend me, grant me wellbeing, provide for me, and raise me.', '', '', '', 'لم يرد فيه أجر مخصوص، وأجره عموم فضل الذكر في الصلاة.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء الجامع بين السجدتين', 'eredienst', 'act of worship', 1, 73),('inside_prayer', 'event', '«التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ»', 'De begroetingen zijn voor Allaah, alsook de gebeden en de goede woorden. Vrede zij met jou, o Profeet, en de barmhartigheid van Allaah en Zijn zegeningen. Vrede zij met ons en met de rechtschapen dienaren van Allaah. Ik getuig dat er geen god is behalve Allaah, en ik getuig dat Muhammad Zijn dienaar en boodschapper is.', 'Greetings are for Allaah, and prayers and good words. Peace be upon you, O Prophet, and the mercy of Allaah and His blessings. Peace be upon us and upon the righteous slaves of Allaah. I bear witness that none has the right to be worshipped except Allaah, and I bear witness that Muhammad is His slave and messenger.', '', '', '', 'لم يرد فيه أجر مخصوص، وأجره عموم فضل الذكر في الصلاة.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'التشهد', 'eredienst', 'act of worship', 1, 74),('inside_prayer', 'event', '«اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ»', 'O Allaah, schenk Uw gebeden aan Muhammad en aan de familie van Muhammad, zoals U Uw gebeden heeft geschonken aan Ibraahiem en aan de familie van Ibraahiem; waarlijk, U bent Geprezen, Glorierijk. O Allaah, zegen Muhammad en de familie van Muhammad, zoals U Ibraahiem en de familie van Ibraahiem heeft gezegend; waarlijk, U bent Geprezen, Glorierijk.', 'O Allaah, send Your prayers upon Muhammad and the family of Muhammad, as You sent Your prayers upon Ibraahiem and the family of Ibraahiem; indeed You are Praiseworthy, Glorious. O Allaah, bless Muhammad and the family of Muhammad, as You blessed Ibraahiem and the family of Ibraahiem; indeed You are Praiseworthy, Glorious.', '', '', '', 'لم يرد فيه أجر مخصوص، وأجره عموم فضل الذكر في الصلاة.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الصلاة الإبراهيمية', 'eredienst', 'act of worship', 1, 75),('inside_prayer', 'event', '«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ جَهَنَّمَ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ»', 'O Allaah, ik zoek toevlucht bij U tegen de bestraffing van het graf, tegen de bestraffing van djahannam, tegen de beproeving van het leven en de dood, en tegen het kwaad van de beproeving van de masieh ad-dadjdjaal.', 'O Allaah, I seek refuge in You from the punishment of the grave, from the punishment of Hell, from the trial of life and death, and from the evil of the trial of the false messiah.', '', '', '', 'أمر صلى الله عليه وسلم بها؛ فهي آكد أدعية ما قبل السلام.', 'Hij (vrede en zegeningen zij met hem) gebood haar; zij is de meest nadrukkelijke smeekbede vóór de salaam.', 'He (peace and blessings be upon him) commanded it; it is the most emphatic supplication before the salaam.', 'التعوذ من الأربع بعد التشهد', 'eredienst', 'act of worship', 1, 76),('inside_prayer', 'event', '«اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ»', 'O Allaah, ik heb mijzelf veel onrecht aangedaan, en niemand vergeeft de zonden behalve U. Schenk mij dus vergeving van bij U en wees mij genadig; waarlijk, U bent de al-Vergevende (al-Ghafoer) en de al-Genadevolle (ar-Rahiem).', 'O Allaah, I have wronged myself greatly, and none forgives sins except You. So grant me forgiveness from You and have mercy on me; indeed You are al-Ghafoor (the Ever-Forgiving), ar-Raheem (the Bestower of Mercy).', '', '', '', 'وصية النبي صلى الله عليه وسلم لأبي بكر رضي الله عنه، تجمع الاعتراف وسؤال المغفرة والرحمة.', 'De aanbeveling van de Profeet (vrede en zegeningen zij met hem) aan Aboe Bakr (moge Allaah tevreden over hem zijn); zij verenigt de bekentenis en het vragen van vergeving en genade.', 'The Prophet''s counsel (peace and blessings be upon him) to Aboo Bakr (may Allaah be pleased with him); it unites confession and the asking of forgiveness and mercy.', 'دعاء الاستغفار قبل السلام', 'eredienst', 'act of worship', 1, 77),('inside_prayer', 'event', '«اللَّهُمَّ إِنِّي أَسْأَلُكَ يَا اللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ الصَّمَدُ، الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ، أَنْ تَغْفِرَ لِي ذُنُوبِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ»', 'O Allaah, ik vraag U, o Allaah — omdat U de al-Ene (al-Waahid) bent, de al-Enige (al-Ahad), de al-Onafhankelijke bij Wie iedereen steun zoekt (as-Samad), Die niet heeft verwekt en niet is verwekt, en aan Wie niemand gelijkwaardig is — dat U mij mijn zonden vergeeft; waarlijk, U bent de al-Vergevende (al-Ghafoer) en de al-Genadevolle (ar-Rahiem).', 'O Allaah, I ask You, O Allaah — for You are al-Waahid (the One), al-Ahad (the Unique), as-Samad (the Eternal Refuge), who neither begets nor is begotten, and to whom none is equal — that You forgive me my sins; indeed You are al-Ghafoor (the Ever-Forgiving), ar-Raheem (the Bestower of Mercy).', '', '', '', 'الأجر منصوص: «قد غُفر له، قد غُفر له» ثلاثا؛ لسؤاله الله باسمه الأعظم.', 'De beloning is uitdrukkelijk: ''hem is vergeven, hem is vergeven'' driemaal, omdat hij Allaah bij Zijn grootste Naam vroeg.', 'The reward is stated: ''he is forgiven, he is forgiven'' three times, for he asked Allaah by His greatest Name.', 'التوسل بالاسم الأعظم', 'eredienst', 'act of worship', 1, 78),('inside_prayer', 'event', '«اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ، وَأَعُوذُ بِكَ مِنَ النَّارِ»', 'O Allaah, ik vraag U om het Paradijs en ik zoek toevlucht bij U tegen het Vuur.', 'O Allaah, I ask You for Paradise and I seek refuge in You from the Fire.', '', '', '', 'أقره صلى الله عليه وسلم على الاقتصار على سؤال الجنة والاستعاذة من النار.', 'Hij (vrede en zegeningen zij met hem) keurde het goed om zich te beperken tot het vragen van het Paradijs en toevlucht tegen het Vuur.', 'He (peace and blessings be upon him) approved confining oneself to asking Paradise and seeking refuge from the Fire.', 'سؤال الجنة والتعوذ من النار', 'eredienst', 'act of worship', 1, 79),('istikharah', 'event', '«اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ؛ فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ. اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ؛ وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ، ثُمَّ أَرْضِنِي بِهِ»', 'O Allaah, ik vraag U om het goede te kiezen door Uw kennis, en ik vraag U om kracht door Uw macht, en ik vraag U van Uw geweldige gunst; want U beschikt en ik beschik niet, U weet en ik weet niet, en U bent de Kenner van het verborgene. O Allaah, als U weet dat deze zaak goed voor mij is in mijn godsdienst, mijn levensonderhoud en de afloop van mijn zaak, beschik haar dan voor mij, maak haar gemakkelijk voor mij en zegen haar voor mij. En als U weet dat deze zaak slecht voor mij is in mijn godsdienst, mijn levensonderhoud en de afloop van mijn zaak, wend haar dan van mij af en wend mij van haar af, en beschik voor mij het goede waar het ook is, en stel mij daarmee tevreden.', '', 'يصلي ركعتين نافلة ثم يدعو به مسميا حاجته، ويمضي لما ينشرح له صدره، ويكررها ما دام مترددا.', 'Men bidt twee vrijwillige rak3ah, smeekt daarna hiermee terwijl men zijn behoefte noemt, gaat door met datgene waarvoor zijn borst zich verruimt, en herhaalt het zolang men twijfelt.', 'One prays two voluntary rak3ahs, then supplicates with it naming one''s need, proceeds with what his heart inclines to, and repeats it as long as one hesitates.', 'لم يرد فيه أجر مخصوص، وفيه تفويض العبد أمره كله لربه؛ وهو عوض ما كان عليه أهل الجاهلية من الاستقسام بالأزلام.', 'Er is geen specifieke beloning overgeleverd; daarin vertrouwt de dienaar zijn hele zaak aan zijn Heer toe; het is de vervanging van wat de mensen van de onwetendheid deden met het lot der pijlen.', 'No specific reward reported; in it the servant entrusts his entire affair to his Lord; it replaces what the people of ignorance did with divining arrows.', 'صلاة الاستخارة', 'toestand', 'state/situation', 1, 80);